# Define local request, response, and normalization helpers for Static Image and Visual Understanding\n\nclass VisionModels:\n    \"\"\"Helper utilities for normalizing inputs and outputs across providers.\n    Provides convenience wrappers for request payloads and response parsing.\n    \"\"\"\n    # -----------------------------------------------------------------------------\n    # Image label detection helpers\n    # -----------------------------------------------------------------------------\n    @staticmethod\n    def format_clarifai_labels(raw_response):\n        \"\"\"Convert Clarifai JSON payload to a standardized list of (name, confidence).\n        Args:\n            raw_response (dict): JSON returned by Clarifai predict_by_filename.\n        Returns:\n            List[Tuple[str, float]]:\n        \"\"\"\n        concepts = raw_response.get(\"outputs\", [{}])[0].get(\"data\", {}).get(\"concepts\", [])\n        return [(c[\"name\"], c[\"value\"]) for c in concepts]\n\n    # -----------------------------------------------------------------------------\n    # Image description (caption) helpers\n    # -----------------------------------------------------------------------------\n    @staticmethod\n    def format_anthropic_caption(raw_response):\n        \"\"\"Extract the generated caption from Anthropic's message response.\n        Args:\n            raw_response (Dict): Anthropic messages.create response.\n        Returns:\n            str: The caption text.\n        \"\"\"\n        return raw_response.get(\"message\", {}).get(\"content\", [{}])[0].get(\"text\", \"\")\n\n    # -----------------------------------------------------------------------------\n    # OCR / text detection helpers\n    # -----------------------------------------------------------------------------\n    @staticmethod\n    def format_azure_ocr(raw_response):\n        \"\"\"Normalize Azure OCR output to a list of (text, bbox).\n        Args:\n            raw_response (Dict): Azure Vision read result.\n        Returns:\n            List[Tuple[str, Tuple[int,int,int,int]]]:\n        \"\"\"\n        lines = []\n        for region in raw_response.get(\"regions\", []):\n            for line in region.get(\"lines\", []):\n                bbox = (line[\"bounding_box\"][\"left\"],\n                        line[\"bounding_box\"][\"top\"],\n                        line[\"bounding_box\"][\"width\"],\n                        line[\"bounding_box\"][\"height\"])\n                lines.append((line[\"text\"], bbox))\n        return lines\n\n    # -----------------------------------------------------------------------------\n    # Safety / guardrails helpers\n    # -----------------------------------------------------------------------------\n    @staticmethod\n    def format_bedrock_safety(raw_response):\n        \"\"\"Interpret Bedrock safety response and return True/False safe flag.\n        Args:\n            raw_response (Dict): Bedrock post_content_moderation result.\n        Returns:\n            bool: True if safe, False otherwise.\n        \"\"\"\n        # Simplified – assume the JSON contains a boolean \"safe\" field\n        return raw_response.get(\"safe\", True)\n\n    # -----------------------------------------------------------------------------\n    # Generic normalization entry point (optional)\n    # -----------------------------------------------------------------------------\n    @staticmethod\n    def normalize(provider: str, raw: dict):\n        \"\"\"Dispatch to the appropriate formatter based on provider name.\n        Args:\n            provider (str): Identifier such as \"clarifai\", \"anthropic\", etc.\n            raw (dict): Raw provider response.\n        Returns:\n            Any: Normalized data.\n        Raises:\n            NotImplementedError if provider not supported.\n        \"\"\"\n        dispatch = {\n            \"clarifai\": VisionModels.format_clarifai_labels,\n            \"anthropic\": VisionModels.format_anthropic_caption,\n            \"azure_ocr\": VisionModels.format_azure_ocr,\n            \"bedrock_safety\": VisionModels.format_bedrock_safety,\n        }\n        formatter = dispatch.get(provider)\n        if not formatter:\n            raise NotImplementedError(f\"No normalizer for provider {provider}\")\n        return formatter(raw)\n\n# -----------------------------------------------------------------------------\n# End of vision_models.py\n# -----------------------------------------------------------------------------
